local MournBuffDisplayCell = Class('MournBuffDisplayCell')
---@type ActivityMournUtils
local ActivityMournUtils = import('Game.Activity.Mourn.ActivityMournUtils')

function MournBuffDisplayCell:__init()

end

function MournBuffDisplayCell:__delete()

end

function MournBuffDisplayCell:Awake()
	SetButtonAction(self.BtnNode,Bind(self,self.OnBtnNodeClick))
end

function MournBuffDisplayCell:SetCallBack(cb)
	self.callBack = cb
end

function MournBuffDisplayCell:RefreshShow(buffId,index)
	self.buffId = buffId
	self.index = index
	local vo = CfUtils.GetCfVo(AutoIds.IdSetting6609, "NightCatGoodsVo", buffId)
	if not vo then
		CfUtils.SetActive(self.StatusNotGet, false)
		CfUtils.SetActive(self.StatusHasGet, false)
		CfUtils.SetUISwitchImage(self.ImgNotSelect, 1)
		return
	end
	
	local isUnlock = ActivityMournUtils.IsUnLockBuff(buffId)
	local isEquip = ActivityMournUtils.IsEquipBuff(buffId)
	
	CfUtils.SetActive(self.StatusNotGet, not isUnlock)
	CfUtils.SetActive(self.StatusHasGet, isUnlock)
	CfUtils.SetUISwitchImage(self.ImgNotSelect, isUnlock and 2 or 1)
	
	if isUnlock then
		CfUtils.FillImage(self.ImgIcon, vo.photoId)
		CfUtils.FillImage(self.ImgIcon2, vo.photoId)
		
		local isMaxLevel = ActivityMournUtils.IsBuffMaxLevel(buffId)
		if isMaxLevel then
			CfUtils.FillText(self.TextLevel, "MAX")
		else
			CfUtils.FillText(self.TextLevel, "Lv."..ActivityMournUtils.GetBuffLevel(buffId))
		end
		CfUtils.SetActive(self.StatusEquip, isEquip)
		
		local isNew = ActivityMournUtils.IsBuffNew(buffId)
		CfUtils.SetActive(self.ImgNew, isNew)
	end
end

function MournBuffDisplayCell:SetSelectState(state)
	CfUtils.SetActive(self.StatusSelect.gameObject, state)
end

function MournBuffDisplayCell:SetImgNewState(state)
	CfUtils.SetActive(self.ImgNew.gameObject,state)
end

function MournBuffDisplayCell:PlayAnimatorState(state)
	CfUtils.PlayAnimator(self.controller, state)
end

function MournBuffDisplayCell:OnBtnNodeClick()
	if self.callBack then
		self.callBack(self.index, self.buffId)
	end
end

function MournBuffDisplayCell:OnDestroy()
	self.controller = nil--luabehaviour 中CSharp对象
	self:Delete()
end

return MournBuffDisplayCell